"phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "20e46981-7707-5d1a-953d-351bfa4ca26b"}, {"title": "李存贞梨园北败邠宁军", "start_year": 895, "end_year": 895, "time_original": "895年冬十月丙戌", "dynasty": "唐", "description": "河东将李存贞在梨园北击败邠宁军，杀千余人；自此梨园守军闭壁不敢出。", "phases": [], "location_name": "梨园北", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3fec7031-e56c-59fc-94fa-5bd232e23afe"}, {"title": "崔昭纬贬梧州司马", "start_year": 895, "end_year": 895, "time_original": "895年十月条；确日未载", "dynasty": "唐", "description": "右仆射崔昭纬被贬为梧州司马。", "phases": [], "location_name": "梧州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f30ee1db-8bd1-5b76-85f3-6f3daa90c19f"}]'::jsonb)
